// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint _minSum, uint _am) public {
        vm.assume(_minSum > 0);
        vm.assume(_am <= _minSum);
        vm.deal(address(this), _am);

        c.SetMinSum(_minSum);
        // Do not call Initialized

        uint beforeMinSum = c.MinSum();

        (bool ok, ) = address(c).call{value: _am}(abi.encodeWithSignature("Collect(uint256)", _am));
        // ok may be false due to revert, but we only care about MinSum

        assertTrue(c.MinSum() == beforeMinSum);
    }
}

